import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"chrome Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"chrome","tag":"chrome","title":"chrome Tag","prev":null,"next":null,"posts":[{"title":"Chrome扩展和Web Page 进行通讯","url":"/posts/2015-08-25-communication-between-extensions-and-web-page/","date":"2015-8-25 19:54","tags":["chrome"],"html":"<p>由于 WEB 页面本身受到浏览器的安全策略限制,而且 Content Scripts 和页面本身并不共享环境变量.我们很多时候都是\\n通过 DOM 去注入 JS 代码到当前页面上.因为同源策略的原因不得不把有些操作发回到 Background 进行处理,因为 Background\\n没有任何限制,可以拥有完整的 Chrome 的 API 权限.</p>\\n<h2 id=\\"通过-content-scripts-中转\\" tabindex=\\"-1\\">通过 Content Scripts 中转 <a class=\\"header-anchor\\" href=\\"#通过-content-scripts-中转\\" aria-label=\\"Permalink to &quot;通过 Content Scripts 中转&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>第一种通讯方式是通过 Web API <a href=\\"https://developer.mozilla.org/en-US/docs/Web/API/Window/postMessage\\" target=\\"_blank\\" rel=\\"noreferrer\\">postMessage</a>\\n发送消息,然后在 Content Scripts 监听 message 事件捕捉消息发送回 Background\\n这种方式适合单向通讯,只从 web page 发送数据到 Background 或者 Background 发送给 web page 如果双向通讯的话就很不方便了\\n因为 Content Scripts 和 web page 共享 window 会造成事件重复绑定的.</p>\\n<h2 id=\\"使用-chrome-api\\" tabindex=\\"-1\\">使用 Chrome API <a class=\\"header-anchor\\" href=\\"#使用-chrome-api\\" aria-label=\\"Permalink to &quot;使用 Chrome API&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先在 manifest.json 里声明权限</p>\\n<div class=\\"language-json line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">json</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#032F62\\">\\"externally_connectable\\"</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"matches\\"</span><span style=\\"color:#24292E\\">: [</span><span style=\\"color:#032F62\\">\\"*://*.example.com/*\\"</span><span style=\\"color:#24292E\\">]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>声明要通讯的网页的网址,然后和 Content Script 一样建立通讯</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> port </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> chrome.runtime.</span><span style=\\"color:#6F42C1\\">connect</span><span style=\\"color:#24292E\\">(chrome_id, { name: </span><span style=\\"color:#032F62\\">'abc'</span><span style=\\"color:#24292E\\"> });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">port.</span><span style=\\"color:#6F42C1\\">postMessage</span><span style=\\"color:#24292E\\">({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  method: </span><span style=\\"color:#032F62\\">'rpc_data'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  data: parameter</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">});</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">port.onMessage.</span><span style=\\"color:#6F42C1\\">addListener</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">response</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  SetMessage</span><span style=\\"color:#24292E\\">(response[</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">], response[</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">});</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br></div></div><p>关键是 Background 监听消息的接收,必须使用 <code>chrome.runtime.onConnectExternal.addListener</code>\\n而不是 <code>chrome.runtime.onConnect.addListener</code>\\n后者是接收 Content Script 消息的,前者是 接收 Web Page 消息的.\\n这样便实现了 Web Page 和 Background 之间的双向通讯, Web Page 不能完成的事情交给 Background 来处理即可.</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developer.chrome.com/extensions/messaging#external-webpage\\" target=\\"_blank\\" rel=\\"noreferrer\\">官方文档</a></p>\\n"},{"title":"Chromebook Pixel (2013) 安装Linux的方法","url":"/posts/2015-04-20-chromebook-pixel-install-linux/","date":"2015-4-20 19:54","tags":["chrome"],"html":"<p>同学最近淘了一台二手 Chromebook Pixel (2013)，这款笔记本最大的诱惑就是 12.85 寸但是配备了一块 2560 x 1700 分辨率的触摸屏。上网的体验不要太爽啊，在体验了一小时的 Chrome OS 之后，便感叹就只有一个浏览器而已啊！于是开始折腾如何安装 Linux，毕竟这款笔记本本来就对 Linux 支持很好。下面开始介绍安装过程。</p>\\n<p>由于这款笔记本是 x86 架构还自带 SeaBIOS，所以在安装 Linux 上省了不少功夫，很多非 SeaBIOS 的 Chromebook 都是需要刷固件才能引导 Linux 的。</p>\\n<h2 id=\\"启用开发者模式\\" tabindex=\\"-1\\">启用开发者模式 <a class=\\"header-anchor\\" href=\\"#启用开发者模式\\" aria-label=\\"Permalink to &quot;启用开发者模式&quot;\\">&ZeroWidthSpace;</a></h2>\\n<ul>\\n<li>启动电脑</li>\\n<li>按住 Esc 和 F3（刷新）按钮，这时候按电源键，即可进入 Recovery 模式</li>\\n<li>按 Ctrl+ D，会提示你是否要进入开发者模式，确认之后等一会系统就会转变成启用开发者模式</li>\\n</ul>\\n<p>这时候每次开机屏幕都有警告提示，要么按 Ctrl + D，或者等待 30s 系统响一声便进入系统。</p>\\n<h2 id=\\"进入超级用户-shell\\" tabindex=\\"-1\\">进入超级用户 shell <a class=\\"header-anchor\\" href=\\"#进入超级用户-shell\\" aria-label=\\"Permalink to &quot;进入超级用户 shell&quot;\\">&ZeroWidthSpace;</a></h2>\\n<ul>\\n<li>按 Ctrl+Alt+F2（→），之后你会看到一个登录提示</li>\\n<li>输入 <code>chronos</code> 作为用户名，没有密码</li>\\n<li>然后输入 <code>sudo bash</code>,以超级用户使用 shell</li>\\n</ul>\\n<h2 id=\\"启用-seabios\\" tabindex=\\"-1\\">启用 SeaBIOS <a class=\\"header-anchor\\" href=\\"#启用-seabios\\" aria-label=\\"Permalink to &quot;启用 SeaBIOS&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>在终端里面输入下面的指令：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># crossystem dev_boot_usb=1 dev_boot_legacy=1</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>之后重启电脑即可。之后每次进入 SeaBIOS 都要在开机的时候按 Ctrl + L</p>\\n<h2 id=\\"将-seabios-设置成默认启动\\" tabindex=\\"-1\\">将 SeaBIOS 设置成默认启动 <a class=\\"header-anchor\\" href=\\"#将-seabios-设置成默认启动\\" aria-label=\\"Permalink to &quot;将 SeaBIOS 设置成默认启动&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先你需要破解硬件写保护，按照 wiki 上的说法需要拆机和跳线，具体的操作可以查看这个<a href=\\"https://www.chromium.org/chromium-os/developer-information-for-chrome-os-devices/chromebook-pixel\\" target=\\"_blank\\" rel=\\"noreferrer\\">wiki</a>,拆机操作非常危险，请自己慎重考虑。</p>\\n<p>如果你已经成功破解硬件写保护，接下来就是解除软件写保护。同样是进入超级用户 shell 然后输入指令禁用软件写保护：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># flashrom --wp-disable</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>检查软件写保护：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># flashrom --wp-status</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>运行 set_gbb_flags.sh ：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># set_gbb_flags.sh</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>注意：新版本的 Chrome OS 已经把这个脚本移动到 <code>/usr/share/vboot/bin/set_gbb_flags.sh</code>位置了，然而并不在$PATH 环境变量中。</p>\\n<p>确认有下面的输出：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>GBB_FLAG_DEV_SCREEN_SHORT_DELAY 0x00000001</span></span>\\n<span class=\\"line\\"><span>GBB_FLAG_FORCE_DEV_SWITCH_ON 0x00000008</span></span>\\n<span class=\\"line\\"><span>GBB_FLAG_FORCE_DEV_BOOT_LEGACY 0x00000080</span></span>\\n<span class=\\"line\\"><span>GBB_FLAG_DEFAULT_DEV_BOOT_LEGACY 0x00000400</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>现在可以设置 SeaBIOS 为默认了：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># set_gbb_flags.sh 0x489</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>最后再重新启用写保护：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># flashrom --wp-enable</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>现在可以使用 Linux 安装 U 盘进行安装了。</p>\\n<h2 id=\\"写在最后\\" tabindex=\\"-1\\">写在最后 <a class=\\"header-anchor\\" href=\\"#写在最后\\" aria-label=\\"Permalink to &quot;写在最后&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>插上 U 盘，开机然后按 Ctrl+ L 发现启动光盘正常启动，然后选择安装之后突然提示。。。</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>not enough memory to load specified image</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这时候不要慌张，在安装选择菜单点击 Tab 键，可以编辑启动命令，在双横线前面输入 <code>mem=4G</code> 注意是双横线前面！</p>\\n<p>恢复 Chrome OS，请参阅<a href=\\"https://support.google.com/chromebook/answer/1080595?hl=en\\" target=\\"_blank\\" rel=\\"noreferrer\\">Recover your Chromebook</a></p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://wiki.archlinux.org/index.php/Chrome_OS_devices\\" target=\\"_blank\\" rel=\\"noreferrer\\">Chrome OS devices</a></p>\\n<p><a href=\\"https://wiki.archlinux.org/index.php/Chrome_OS_devices/Chromebook\\" target=\\"_blank\\" rel=\\"noreferrer\\">Chromebook</a></p>\\n<p><a href=\\"http://vger.kernel.org/~davem/chromebook_pixel_linux.txt\\" target=\\"_blank\\" rel=\\"noreferrer\\">Installing Linux on the Chromebook Pixel</a></p>\\n"},{"title":"chrome扩展开发经验记录","url":"/posts/2014-08-23-chrome-extension-develop/","date":"2014-08-23 16:01","tags":["chrome"],"html":"<p>最近写了两个 chrome 扩展.看了不少 chrome 扩展开发的文档.觉得还是写点东西比较好.</p>\\n<h2 id=\\"background-pages\\" tabindex=\\"-1\\">Background Pages <a class=\\"header-anchor\\" href=\\"#background-pages\\" aria-label=\\"Permalink to &quot;Background Pages&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>一个扩展肯定需要长时间运行的脚本对扩展进行管理.这个脚本就属于 Background Pages 的一部分.\\n不过由于 Background Pages 是一直运行的,对资源占用比较多.现在已经用 Event Pages 代替.Event Pages 是按需加载,不需要的时候不会激活运行.\\nEvent Pages 的 JS 可以使用 chrome 的所有 API.</p>\\n<p><a href=\\"https://developer.chrome.com/extensions/event_pages\\" target=\\"_blank\\" rel=\\"noreferrer\\">官方文档</a></p>\\n<h2 id=\\"content-scripts\\" tabindex=\\"-1\\">Content Scripts <a class=\\"header-anchor\\" href=\\"#content-scripts\\" aria-label=\\"Permalink to &quot;Content Scripts&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Content Scripts 是运行在网页上的. manifest 上进行网址匹配.当是目标网址的时候就加载这个 JS.\\nContent Scripts 可以获取到匹配网址的 DOM,并进行修改.Content Scripts 也可以使用 chrome 的 API,但是只能使用比较有限的 API.</p>\\n<p><a href=\\"https://developer.chrome.com/extensions/content_scripts\\" target=\\"_blank\\" rel=\\"noreferrer\\">官方文档</a></p>\\n<h2 id=\\"message-passing\\" tabindex=\\"-1\\">Message Passing <a class=\\"header-anchor\\" href=\\"#message-passing\\" aria-label=\\"Permalink to &quot;Message Passing&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>这个是 chrome 的通讯机制,是非常重要的一个知识点.开发扩展的 content scripts 几乎都是需要和 background pages 进行通讯的.\\n因为 content scripts 可以直接操作 DOM,background pages 可以使用所有的 chromeAPI.所以这俩 JS 肯定要互通有无.接下来重点讲解 chrome 的通讯机制.</p>\\n<p><a href=\\"https://developer.chrome.com/extensions/messaging\\" target=\\"_blank\\" rel=\\"noreferrer\\">官方文档</a></p>\\n<h3 id=\\"simple-one-time-requests\\" tabindex=\\"-1\\">Simple one-time requests <a class=\\"header-anchor\\" href=\\"#simple-one-time-requests\\" aria-label=\\"Permalink to &quot;Simple one-time requests&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>官方文档有例子.但是我要说的是这个 Simple requests 真的太 Simple.\\ncontent js 使用 sendMessage,就立即回调获取 response.\\n如果 background page 稍微进行处理下占用点时间就会导致 response 的函数根本无法执行的情况.\\n推测可能是没接收到数据就直接 pass 了.所以稍微复杂点需要处理数据的通讯操作千万不能用这个.</p>\\n<h3 id=\\"long-lived-connections\\" tabindex=\\"-1\\">Long-lived connections <a class=\\"header-anchor\\" href=\\"#long-lived-connections\\" aria-label=\\"Permalink to &quot;Long-lived connections&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>这个通讯方式也是我比较推荐的通讯方式,生命周期长.并且通讯效果好,可以多次通讯一次监听.\\n官网给出的 content js 例子虽然是先 postMessage 之后再 addListener.但是强烈推荐先\\n监听之后再发送数据.因为当你发送数据之后,background 可能会立马给你返回数据.这时候可能会造成\\n没有监听到的情况... 之后的通讯方式我还没用到就不说了.</p>\\n<h2 id=\\"网页-js-和-content-js-通讯\\" tabindex=\\"-1\\">网页 JS 和 content js 通讯 <a class=\\"header-anchor\\" href=\\"#网页-js-和-content-js-通讯\\" aria-label=\\"Permalink to &quot;网页 JS 和 content js 通讯&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>网页 JS 也有自己的局限性,例如无法获取到 http only 的 cookies.这时候可以通过 content js 的帮助.\\ncontent js 获取到数据之后怎么发给网页 JS 呢?\\ncontent js 使用 window.postMessage 进行发送数据:</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">window.</span><span style=\\"color:#6F42C1\\">postMessage</span><span style=\\"color:#24292E\\">(msg, </span><span style=\\"color:#032F62\\">'*'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>网页 JS 通过监听事件进行捕捉数据:</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">window.</span><span style=\\"color:#6F42C1\\">addEventListener</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'message'</span><span style=\\"color:#24292E\\">, receiveMessage, </span><span style=\\"color:#005CC5\\">false</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> receiveMessage</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">event</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (event.origin </span><span style=\\"color:#D73A49\\">==</span><span style=\\"color:#24292E\\"> window.location.origin) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(event.data);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br></div></div><p>注意 content js 和网页 JS 不共享变量,所以不能通过全局变量的方式进行通讯.不过可以通过 DOM 进行通讯.</p>\\n<h2 id=\\"content-js-使用网页-js-的变量\\" tabindex=\\"-1\\">content js 使用网页 JS 的变量. <a class=\\"header-anchor\\" href=\\"#content-js-使用网页-js-的变量\\" aria-label=\\"Permalink to &quot;content js 使用网页 JS 的变量.&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>如果网页本身加载了很多组件例如 JQuery,自己想使用但是因为不共享变量导致无法使用.可以使用 append 的\\n方式把自己 content js 里面写的函数直接注入到网页的 DOM 中,因为 DOM 是共享的.这样 content js 写的函数\\n就变成网页的 JS 进行运行了~</p>\\n<h2 id=\\"content-js-注入\\" tabindex=\\"-1\\">content js 注入 <a class=\\"header-anchor\\" href=\\"#content-js-注入\\" aria-label=\\"Permalink to &quot;content js 注入&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> script </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> document.</span><span style=\\"color:#6F42C1\\">createElement</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'script'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">script.id </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'baidu_script'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">script.</span><span style=\\"color:#6F42C1\\">appendChild</span><span style=\\"color:#24292E\\">(document.</span><span style=\\"color:#6F42C1\\">createTextNode</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'('</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#24292E\\"> baidu </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\"> ')();'</span><span style=\\"color:#24292E\\">));</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">(document.body </span><span style=\\"color:#D73A49\\">||</span><span style=\\"color:#24292E\\"> document.head </span><span style=\\"color:#D73A49\\">||</span><span style=\\"color:#24292E\\"> document.documentElement).</span><span style=\\"color:#6F42C1\\">appendChild</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  script</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br></div></div><p>这里注入的是一个立即执行函数,append 到 DOM 上的时候就会立即执行,并且可以使用网页 JS 的变量.</p>\\n<h2 id=\\"css-注入\\" tabindex=\\"-1\\">css 注入 <a class=\\"header-anchor\\" href=\\"#css-注入\\" aria-label=\\"Permalink to &quot;css 注入&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>有时候修改 DOM 的话肯定需要更改样式啊,这时候用内联样式必然太没效率,不能重用.就需要添加 CSS.</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#6F42C1\\"> css</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#24292E\\"> () {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  /*</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  input{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  border: 1px solid #C6C6C6;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  box-shadow: 0 0 3px #C6C6C6;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  -webkit-box-shadow: 0 0 3px #C6C6C6;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  */</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  .</span><span style=\\"color:#6F42C1\\">toString</span><span style=\\"color:#24292E\\">()</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  .</span><span style=\\"color:#6F42C1\\">slice</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">15</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#005CC5\\">4</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> style </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> document.</span><span style=\\"color:#6F42C1\\">createElement</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'style'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">style.</span><span style=\\"color:#6F42C1\\">setAttribute</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'type'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'text/css'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">style.textContent </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> css;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">document.head.</span><span style=\\"color:#6F42C1\\">appendChild</span><span style=\\"color:#24292E\\">(style);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br></div></div><p>首先定义一个匿名函数赋值给 css 变量,然后里面写了 css 内容,由于是注释掉的,其实并不会被 JS 执行,最后\\n转换成字符串的时候是能读到 CSS 文本的,slice 是去掉前后的注释符.</p>\\n"}]},"relativePath":"tags/chrome/index.md","filePath":"tags/[slug].md"}`),e={name:"tags/chrome/index.md"};function p(l,o,r,t,c,i){return n(),a("div")}const h=s(e,[["render",p]]);export{b as __pageData,h as default};
